import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { GRADES } from '../people/usePeople';
import { useSheetToday } from '../sheet/useSheet';
import { claimRateOn, PCT, rateOn, ratesKey, totalDue, useRates, type Rate } from './useRates';
import { claimDueCents, isOpen, useClaims } from '../claims/useClaims';
import { gradeOn, usePeople } from '../people/usePeople';
import { useFloor, useLate } from '../settings/useSettings';

/**
 * The rate in force on the sheet's today for each grade, every rate set (by grade, then from-date),
 * and one form to set a grade's rate, from a date or (left blank) from the beginning of time, through a date or (left blank) with no end.
 */
function RatesPanel({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const [grade, setGrade] = useState<string>('A');
  const [pct, setPct] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [invalid, setInvalid] = useState(false);

  const submitOnce = useSubmitOnce();
  const save = useMutation({
    mutationFn: (r: { grade: string; pct: string; from: string; to: string }) =>
      postJson<Rate>(`/api/sheets/${encodeURIComponent(sheet)}/rates`, { ...r, user }),
    onSuccess: async () => {
      setPct('');
      setFrom('');
      setTo('');
      await queryClient.invalidateQueries({ queryKey: ratesKey(sheet) });
    },
  });

  // An error goes as soon as its form is changed or submitted again.
  const clearError = () => {
    save.reset();
    setInvalid(false);
  };

  return (
    <section data-testid="rates-panel">
      <h2>Rates</h2>
      <form
        data-testid="rate-form"
        onSubmit={(e) => {
          e.preventDefault();
          if (!PCT.test(pct.trim())) {
            // Refused here, before anything is sent: the store and the audit file are untouched.
            save.reset();
            setInvalid(true);
            return;
          }
          setInvalid(false);
          submitOnce(() => save.mutateAsync({ grade, pct: pct.trim(), from: from.trim(), to: to.trim() }));
        }}
      >
        <label>
          Grade{' '}
          <select
            data-testid="rate-form-grade"
            value={grade}
            onChange={(e) => {
              setGrade(e.target.value);
              clearError();
            }}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          Rate %{' '}
          <input
            data-testid="rate-form-pct"
            placeholder="0.00"
            value={pct}
            onChange={(e) => {
              setPct(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <label>
          From{' '}
          <input
            data-testid="rate-form-from"
            placeholder="yyyy-mm-dd"
            value={from}
            onChange={(e) => {
              setFrom(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <label>
          To{' '}
          <input
            data-testid="rate-form-to"
            placeholder="yyyy-mm-dd"
            value={to}
            onChange={(e) => {
              setTo(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {(invalid || save.isError) && (
          <span data-testid="rate-form-error" role="alert">
            {' '}
            {invalid
              ? 'The rate must be a percent, 0.00 or more, with up to two decimals.'
              : 'Could not set this rate.'}
          </span>
        )}
      </form>
      <RatePreview sheet={sheet} />
      <table data-testid="rate-current">
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate % today</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              <td data-testid={`rate-current-${g}`}>{rateOn(rates, g, today) ?? 'n/a'}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="rate-list">
        <thead>
          <tr>
            <th>Grade</th>
            <th>From</th>
            <th>To</th>
            <th>Rate %</th>
            <th>Versions</th>
          </tr>
        </thead>
        <tbody>
          {rates.filter((r) => (r.level ?? 0) === 0).map((r) => (
            <tr key={`${r.grade}-${r.from ?? 'start'}`} data-testid={`rate-row-${r.grade}-${r.from ?? 'start'}`}>
              <td>{r.grade}</td>
              <td data-testid="rate-from">{r.from ?? 'start'}</td>
              <td data-testid="rate-to">{r.to ?? ''}</td>
              <td>
                <span data-testid="rate-pct">{r.pct}</span>
              </td>
              <td data-testid="rate-version">{r.version}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

/**
 * A preview of a candidate rate for a grade, saving nothing: how many OPEN and PENDING claims of
 * people on that grade (the grade in force on the claim's date) would show a different due if the
 * rate applied to the grade on every date and to every claim, and the differences (new due minus current,
 * each claim's current at the rate that applies to it, see `claimRateOn`) added up.
 * A claim bound by a statement keeps its figure, so it does not change; a settled claim is not counted.
 */
function RatePreview({ sheet }: { sheet: string }) {
  const claimsQuery = useClaims(sheet);
  const peopleQuery = usePeople(sheet);
  const ratesQuery = useRates(sheet);
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const [grade, setGrade] = useState<string>('A');
  const [pct, setPct] = useState('');
  const [invalid, setInvalid] = useState(false);
  const [running, setRunning] = useState(false);
  const [result, setResult] = useState<{ count: number; diff: string } | null>(null);

  const preview = async () => {
    setResult(null);
    if (!PCT.test(pct.trim())) {
      setInvalid(true);
      return;
    }
    setInvalid(false);
    setRunning(true);
    try {
      // Re-read, so the preview goes by what the store holds now.
      const [claims, people, rates] = await Promise.all([claimsQuery.refetch(), peopleQuery.refetch(), ratesQuery.refetch()]);
      const byId = new Map((people.data ?? []).map((p) => [p.id, p]));
      const candidate = pct.trim();
      let count = 0;
      let diff = 0n;
      for (const c of claims.data ?? []) {
        const person = byId.get(c.personId);
        if (!isOpen(c) || person === undefined || gradeOn(person, c.date) !== grade) continue;
        const current = claimDueCents(c, floor, claimRateOn(rates.data ?? [], grade, c), late);
        const next = claimDueCents(c, floor, candidate, late);
        if (current === next) continue;
        count++;
        diff += (next ?? 0n) - (current ?? 0n);
      }
      setResult({ count, diff: totalDue([diff]) });
    } finally {
      setRunning(false);
    }
  };

  return (
    <form
      data-testid="rate-preview-form"
      onSubmit={(e) => {
        e.preventDefault();
        void preview();
      }}
    >
      <label>
        Preview grade{' '}
        <select
          data-testid="rate-preview-grade"
          value={grade}
          onChange={(e) => {
            setGrade(e.target.value);
            setInvalid(false);
            // A result goes as soon as the form is changed.
            setResult(null);
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
      </label>{' '}
      <label>
        Candidate rate %{' '}
        <input
          data-testid="rate-preview-pct"
          placeholder="0.00"
          value={pct}
          onChange={(e) => {
            setPct(e.target.value);
            setInvalid(false);
            // A result goes as soon as the form is changed.
            setResult(null);
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="rate-preview" disabled={running}>
        Preview
      </button>
      {result !== null && (
        <span>
          {' '}
          Claims changing: <span data-testid="rate-preview-count">{result.count}</span>, difference:{' '}
          <span data-testid="rate-preview-diff">{result.diff}</span>
        </span>
      )}
      {invalid && (
        <span data-testid="rate-preview-error" role="alert">
          {' '}
          The rate must be a percent, 0.00 or more, with up to two decimals.
        </span>
      )}
    </form>
  );
}

export const contribution = SheetPanels.fill({ order: 5, Component: RatesPanel });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, useAsOf } from '../asof/useAsOf';

/** A grade's rate as the server sends it: `pct` is a percent with two decimals, `from` the date it
 *  is in force from (yyyy-mm-dd), or null when it applies from the beginning of time; `to` the
 *  date it applies through, or null when it has no end; `version` how many values have been set for
 *  its grade and from-date, this newest one (the one in force) included. */
export type Rate = {
  grade: string;
  pct: string;
  from: string | null;
  to: string | null;
  version: number;
  /** Set for a forward-only rate (saved with a from-date on or after the sheet's today): it applies only to
   *  claims whose `seq` is higher. Null when it applies to every claim. */
  forwardAfter: number | null;
  /** Its grade and from-date's older versions, newest first: a claim a forward-only version does not apply
   *  to takes the newest of them that does. */
  earlier: RateVersion[];
  level?: number;
};

/** An older version of a rate, as it was set. */
type RateVersion = { pct: string; to: string | null; forwardAfter: number | null };

/** The rates of one of the sheet's parent sheets, `level` levels up (1 for the parent). */
type InheritedRates = { level: number; sheet: string; rates: Rate[] };

export const ratesKey = (sheet: string) => ['sheet', sheet, 'rates'] as const;

/** The sheet's own rates, by grade then from-date (the one with none first), each with `level` 0;
 *  then the rates of its parent sheets, nearest first, up to three levels up, each with the level it
 *  is from (1 for the parent). Re-read whenever the sheet is loaded. */
export function useRates(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(ratesKey(sheet), asOf),
    queryFn: async () => {
      const base = `/api/sheets/${encodeURIComponent(sheet)}`;
      const [own, inherited] = await Promise.all([
        getJson<Rate[]>(asOfPath(`${base}/rates`, asOf)),
        getJson<InheritedRates[]>(asOfPath(`${base}/rates/inherited`, asOf)),
      ]);
      return [
        ...own.map((r) => ({ ...r, level: 0 })),
        ...inherited.flatMap((i) => i.rates.map((r) => ({ ...r, level: i.level }))),
      ];
    },
    staleTime: 0,
    gcTime: 0,
  });
}

/** A percent the server accepts: 0.00 or more, with up to two decimals. */
export const PCT = /^\d{1,5}(\.\d{1,2})?$/;

/**
 * The grade's rate in force on `date` (yyyy-mm-dd): the sheet's own (level 0) when it has one then,
 * else its parent's then, and so on up the levels.
 */
export function rateOn(rates: Rate[], grade: string, date: string): string | undefined {
  const levels = [...new Set(rates.map((r) => r.level ?? 0))].sort((a, b) => a - b);
  for (const level of levels) {
    const pct = levelRateOn(rates.filter((r) => (r.level ?? 0) === level), grade, date);
    if (pct !== undefined) return pct;
  }
  return undefined;
}

/**
 * The grade's rate in force on `date` among `rates` (of one sheet): the one whose from-date is the latest on or
 * before it, a rate with no from-date applying from the beginning of time. Undefined when none does, or when that one's to-date is before `date`.
 */
function levelRateOn(rates: Rate[], grade: string, date: string): string | undefined {
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  return found !== undefined && (found.to === null || found.to >= date) ? found.pct : undefined;
}

/**
 * The grade's rate that applies to a claim on its date: as `rateOn`, but passing over each forward-only
 * rate saved after the claim was added — for the newest older version of its from-date that applies to
 * the claim, else for the from-date before. The rates panel and the preview's candidate go by `rateOn`.
 */
export function claimRateOn(rates: Rate[], grade: string, claim: { date: string; seq: number }): string | undefined {
  const applies = (v: { forwardAfter: number | null }) => v.forwardAfter === null || claim.seq > v.forwardAfter;
  const applying: Rate[] = [];
  for (const r of rates) {
    const v = applies(r) ? r : r.earlier.find(applies);
    if (v !== undefined) applying.push({ ...r, pct: v.pct, to: v.to, forwardAfter: v.forwardAfter });
  }
  return rateOn(applying, grade, claim.date);
}

/** "12.34" as a whole number of hundredths (1234n), exactly. */
export function hundredths(value: string): bigint {
  const negative = value.startsWith('-');
  const [whole, frac = ''] = (negative ? value.slice(1) : value).split('.');
  const cents = BigInt(whole) * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -cents : cents;
}

function format(cents: bigint): string {
  const abs = cents < 0n ? -cents : cents;
  return `${cents < 0n ? '-' : ''}${abs / 100n}.${(abs % 100n).toString().padStart(2, '0')}`;
}

/**
 * What is due on `amount` (two decimals) at `pct` percent: amount times pct divided by 100,
 * rounded to two decimals (half up with `halfUp`, else half to even), worked in whole numbers so it
 * is exact. In cents, or null when there is no rate.
 */
export function dueCents(amount: string, pct: string | undefined, halfUp = false): bigint | null {
  if (pct === undefined) return null;
  // cents * hundredths-of-a-percent is in ten-thousandths of a cent.
  // Rounded on its size, so a negative amount (a correction) rounds like a positive one.
  const product = hundredths(amount) * hundredths(pct);
  const abs = product < 0n ? -product : product;
  const rounded = roundTenThousandths(abs, halfUp);
  return product < 0n ? -rounded : rounded;
}

/** A size in ten-thousandths of a cent, rounded to whole cents: half up with `halfUp`, else half to even. */
export function roundTenThousandths(abs: bigint, halfUp: boolean): bigint {
  const whole = abs / 10000n;
  const rest = abs % 10000n;
  return rest > 5000n || (rest === 5000n && (halfUp || whole % 2n === 1n)) ? whole + 1n : whole;
}

/** A due in cents as shown: two decimals, or n/a when there is no rate. */
export function showDue(cents: bigint | null): string {
  return cents === null ? 'n/a' : format(cents);
}

/** Dues added up, skipping the n/a ones. */
export function totalDue(dues: Array<bigint | null>): string {
  return format(dues.reduce<bigint>((sum, d) => (d === null ? sum : sum + d), 0n));
}

/** The figures (n/a skipped) added up, leaving out the single highest and lowest when three or more. */
export function trimmedTotal(dues: Array<bigint | null>): string {
  const figures = dues.filter((d): d is bigint => d !== null).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  return totalDue(figures.length >= 3 ? figures.slice(1, -1) : figures);
}

